@app.route('/api/v1/avatar', methods=['POST'])
def upload_avatar():
    file = request.files.get('file')
    user_id = request.form.get('userId')
    if not file or not user_id:
        return jsonify({'status': 0, 'msg': 'Missing parameters'}), 400
    file.save(os.path.join(UPLOAD_FOLDER, f'{user_id}.jpg'))
    return jsonify({'status': 1, 'msg': 'Success', 'avatarUrl': f'/avatars/{user_id}.jpg'})
